from pathlib import Path
import re, shutil
from html import escape

root=Path(__file__).parent
out=root/'join-hbx-solar';out.mkdir(exist_ok=True)
source=(root/'index.html').read_text(encoding='utf-8-sig')
header=re.search(r'<header class="hbx-header".*?</header>',source,re.S).group()
header=re.sub(r' (href|src)="(?!https?:|tel:|/|#)([^"]+)"',r' \1="/\2"',header)
header=header.replace(' aria-current="page"','').replace('</div>\n<a class="hbx-header__call"','<a href="/join-hbx-solar/" aria-current="page">Join HBX Solar</a></div>\n<a class="hbx-header__call"')
shutil.copyfile(root/'wp-content/uploads/2026/01/cropped-Kusaaa-solar-logo.png',out/'hbx-solar-logo.png')
header=header.replace('/wp-content/uploads/2026/01/cropped-Kusaaa-solar-logo.png','/join-hbx-solar/hbx-solar-logo.png')
footer=re.search(r'<footer\b.*?</footer>',source,re.S).group()
footer=re.sub(r' (href|src)="(?!https?:|tel:|/|#)([^"]+)"',r' \1="/\2"',footer)
footer=re.sub(r'https?://(?:www\.)?kusaaasolar.com', '',footer,flags=re.I)
footer=re.sub('kusaaa', 'hbx',footer,flags=re.I)
footer=footer.replace('/../','/').replace('/&quot;','').replace('&quot;"','"')
footer=footer.replace('animate-in','').replace('pix-opacity-0','')

def items(xs):return '<ul>'+''.join('<li>'+escape(x)+'</li>' for x in xs)+'</ul>'
def cards(xs):return '<div class="cards">'+''.join(f'<article class="card"><span class="number">{i:02}</span><h3>{a}</h3><p>{b}</p></article>' for i,(a,b) in enumerate(xs,1))+'</div>'
def section(id,kicker,title,body,cls=''):
 return f'<section id="{id}" class="section {cls}"><div class="wrap"><div class="section-head"><span class="eyebrow">{kicker}</span><h2>{title}</h2></div>{body}</div></section>'

parts=['''<main id="main"><section class="hero"><div class="wrap hero-grid"><div><span class="eyebrow">CAREERS • SALES • SOLAR ENERGY</span><h1>Build Your Career<br>with <em>HBX Solar</em></h1><h2>Learn Solar. Build Customers.<br>Grow with HBX Solar.</h2><p>Start your journey in India’s growing solar energy industry with structured training, practical sales experience and a performance-driven career path — all with the flexibility of working from home.</p><div class="actions"><a class="button" href="#application">Apply Now <span>↗</span></a><a class="button secondary" href="#how-it-works">Explore the Program <span>↓</span></a></div><div class="location">Azamgarh District &amp; surrounding areas <span>•</span> Sales &amp; business development</div></div><div class="hero-media"><img src="/wp-content/uploads/2026/04/img-1-1024x683.webp" width="1024" height="683" alt="Solar panels capturing sunlight under a clear sky" fetchpriority="high"><div class="media-label"><span>YOUR NEXT CHAPTER</span><strong>A brighter future.<br>Built by you.</strong><div>LEARN <b>→</b> PERFORM <b>→</b> GROW</div></div><div class="training-tag"><strong>30</strong><span>days of structured<br>solar sales training</span></div></div></div></section><div class="value-strip"><div class="wrap"><span>⌂ &nbsp; Work From Home</span><span>30-Day Training</span><span>Performance Growth</span><span>Solar Industry</span><span>Career Opportunity</span></div></div><nav class="section-nav" aria-label="Explore this page"><div class="wrap"><a href="#overview">The opportunity</a><a href="#how-it-works">Your journey</a><a href="#training">Training</a><a href="#compensation">Growth &amp; compensation</a><a href="#faq">FAQs</a><a href="#application">Apply now ↗</a></div></nav>''']
