parts.append(section('how-it-works','LEARN → START → ACQUIRE → GROW','Your Journey with HBX Solar','<div class="journey">'+''.join(f'<article><span class="milestone">{i:02}</span><h3>{a}</h3><p>{b}</p></article>' for i,(a,b) in enumerate(journey,1))+'</div>','dark'))
modules=[('Solar Fundamentals',['Solar PV basics','System sizing: 1kW / 2kW / 3kW / 5kW systems','Solar panels and inverters','Mounting structures','Basic electrical concepts','Rooftop solar fundamentals']),('Customer Understanding',['Understanding customer requirements','Electricity consumption','Customer qualification','Identifying suitable solar solutions','Handling customer questions']),('Sales & Communication',['Calling techniques','WhatsApp communication','Lead generation and customer presentation','Objection handling and follow-ups','Negotiation basics','Customer conversion']),('HBX Solar Sales Process',['Lead management and CRM usage','Quotation process','Customer follow-up','Documentation','Internal communication','Reporting and handover process'])]
parts.append(section('training','A STRONG FOUNDATION','30 Days to Build Your Solar Sales Foundation','<p class="lead">Learn the Industry. Learn the Product. Learn the Customer. Learn the Sale.</p><div class="modules">'+''.join(f'<article class="card"><span class="eyebrow">MODULE {i:02}</span><h3>{a}</h3>{items(b)}</article>' for i,(a,b) in enumerate(modules,1))+'</div><p class="note">Training content may be updated according to HBX Solar’s current products, processes and business requirements.</p>'))
parts.append(section('compensation','TRANSPARENT EXPECTATIONS','Performance-Driven Career Structure','''<div class="split compensation"><div><h3>Your growth is connected to your performance.</h3><p>The compensation structure is based on successful customer acquisition and company-defined performance criteria.</p><div class="support"><h4>Performance Support</h4><p>Where applicable, HBX Solar may provide limited performance support during the initial period, subject to company policy, activity requirements and eligibility criteria.</p></div></div><div><table><caption>Monthly compensation by performance stage</caption><thead><tr><th>Performance</th><th>Monthly compensation</th></tr></thead><tbody><tr><td>Initial employment stage</td><td>₹8,000</td></tr><tr><td>5 successful customers</td><td>₹11,000</td></tr><tr><td>6 successful customers</td><td>₹14,000</td></tr><tr><td>7+ customers</td><td>Higher performance opportunity / additional incentive</td></tr></tbody></table></div></div><p class="note">Customer acquisition will be counted only when the customer meets HBX Solar’s defined qualification criteria. The exact definition of a successful customer, payment/booking requirements, applicable incentives and salary terms will be communicated in the official employment documentation.</p><p class="terms">All compensation, employment status, targets and incentives are subject to the official HBX Solar employment terms and applicable company policies.</p>''','tint'))
parts.append(section('first-customer','YOUR FIRST MILESTONE','Your First Customer Can Be Your First Milestone','''<p class="lead">Your first successful customer acquisition is an important milestone in the HBX Solar career journey. Once you meet the company’s defined criteria, you can move into the official employment stage.</p><div class="path"><span>Training<br><strong>Associate</strong></span><span>First successful<br><strong>Customer</strong></span><span>Official HBX Solar<br><strong>Employee</strong></span><span>Career &amp; performance<br><strong>Growth</strong></span></div><h3>After employment confirmation, eligible employees may receive</h3><div class="pills"><span>HBX Solar Official Email ID</span><span>Employee ID Card</span><span>HBX Solar T-Shirt</span><span>Official Sales Resources</span><span>CRM / Reporting Access</span></div><p class="note">Company-provided physical materials will be dispatched to the employee’s registered address where applicable.</p>'''))
