parts.append(section('milestones','MAKE YOUR PROGRESS COUNT','Performance Creates Opportunity','<div class="growth-grid">'+''.join(f'<article><strong>{a}</strong><p>{b}</p></article>' for a,b in [('1st Customer','Entry milestone'),('4 Customers','Initial monthly target'),('5 Customers','₹11,000 compensation slab'),('6 Customers','₹14,000 compensation slab'),('20 Customers','Performance milestone / recognition eligibility'),('High Performance','Senior responsibilities / team leadership opportunities')])+'</div><p class="note">Eligibility for higher responsibilities may be based on sustained performance, business requirements and company evaluation.</p>'))
parts.append(section('career','THINK LONG TERM','Where Can This Journey Take You?','<div class="career-path">'+''.join('<span>'+x+'</span>' for x in ['Sales Associate','Senior Sales Associate','Business Development Executive','Team Leader','Sales / Business Development Manager'])+'</div><p class="note">Career progression depends on sustained performance, skills, leadership capability, business requirements and company evaluation.</p>','dark'))
parts.append(section('role','MEANINGFUL WORK. REAL RESPONSIBILITY.','Your Role at HBX Solar','<div class="role-list">'+items(['Generate and develop solar leads','Contact potential customers','Understand customer electricity and solar requirements','Explain suitable solar solutions','Conduct follow-ups','Coordinate with the internal sales/technical team','Maintain customer information in the CRM','Track leads and opportunities','Support customers throughout the sales process','Achieve assigned customer acquisition targets','Maintain professional communication','Submit regular sales/activity reports'])+'</div>'))
parts.append(section('expectations','BRING YOUR COMMITMENT','What We Expect','<div class="split"><article class="card"><h3>We Value</h3><div class="pills">'+''.join('<span>'+x+'</span>' for x in ['Discipline','Communication','Consistency','Customer focus','Learning attitude','Accountability','Professionalism','Integrity'])+'</div></article><article class="card"><h3>We Don’t Expect</h3>'+items(['Years of solar experience','A traditional office setup','Perfect sales skills on day one'])+'</article></div><p class="highlight">We can teach the process. You bring the commitment.</p>','tint'))
parts.append(section('resources','EQUIPPED TO MOVE FORWARD','More Than Just a Sales Role',cards([('Official Company Identity','HBX Solar email ID and employee identity resources after meeting applicable employment criteria.'),('Professional Training','Structured training to develop solar and sales knowledge.'),('Digital Tools','CRM, communication and reporting systems according to role requirements.'),('Company Branding','Eligible employees receive company-branded materials as applicable.'),('Performance Recognition','Recognition opportunities based on achievement and sustained performance.'),('Growth Opportunities','Potential progression into senior sales and leadership roles.')])) )
faq=[('Is this a work-from-home opportunity?','Yes. The program is designed around a Work From Home sales model for eligible candidates.'),('Do I need previous solar experience?','No. Candidates can enter through the structured training program, subject to selection.'),('Is the training paid?','Training payment terms have not yet been published on this page. Please confirm the current policy with HBX Solar’s recruitment team before joining training.'),('When does employment begin?','Official employment begins after you meet the company’s defined employment and confirmation criteria, as set out in the official documentation.'),('What happens after my first customer?','After your first successful customer and completion of the defined criteria, you can move into the official employment stage.'),('How is salary determined?','Compensation is linked to verified customer acquisition and company-defined performance criteria. See the compensation structure above; the official employment terms govern eligibility, targets and payment.'),('Can I work from anywhere?','The primary recruitment focus is Azamgarh District. Candidates from surrounding areas should confirm geographic eligibility with recruitment. Wider eligibility has not been confirmed.'),('What happens if I don’t acquire customers?','The applicable performance review process and any initial support depend on company policy and your official terms. Ask recruitment to explain targets, review periods and the consequences of not meeting them before accepting the opportunity.'),('How are customers counted?','Only acquisitions verified under HBX Solar’s official sales policy count. The precise qualification, booking and payment requirements must be confirmed in the official employment documentation; a lead or enquiry should not be assumed to count.'),('Can I grow into a leadership role?','Yes, subject to sustained performance, capability, business requirements and company evaluation.')]
